# -*- coding: utf-8 -*-
"""手机端界面文件（打进 APK；运行时解压到应用私有目录）。

Chaquopy 会把 python 目录打成 .imy（本质是 zip），Python 里没法直接 open() 读，
所以把前端文件 base64 塞进这里，start() 时解出来给 http.server 用。

这个文件由 _gen_webpack.py 自动生成，别手改。
"""
import base64
import os

FILES = {
    'm.html': '',
    'm.css': '',
    'm.js': '',
    'manifest.webmanifest': '',
    'sw.js': '',
    'icon-192.png': '',
    'icon-512.png': '',
}


def extract(dirpath):
    """把所有界面文件写到 dirpath，返回该目录。大小一致就跳过，避免每次启动重写。"""
    os.makedirs(dirpath, exist_ok=True)
    for name, b64 in FILES.items():
        dest = os.path.join(dirpath, name)
        raw = base64.b64decode(b64)
        try:
            if os.path.getsize(dest) == len(raw):
                continue
        except OSError:
            pass
        with open(dest, "wb") as fh:
            fh.write(raw)
    return dirpath
